-- BELONG demo seed: communities and memberships
-- Requires: supabase/seeds/01-users.sql

on conflict (id) do update set
  name = excluded.name,
  description = excluded.description,
  tag = excluded.tag;

on conflict (community_id, user_id) do nothing;

select v.user_id, v.community_id, v.contribution_type, v.points
from (values
  ('d1000000-0000-4000-8000-000000000001'::uuid, 'd3000000-0000-4000-8000-000000000001'::uuid, 'post', 10),
  ('d1000000-0000-4000-8000-000000000002', 'd3000000-0000-4000-8000-000000000002', 'post', 10),
  ('d1000000-0000-4000-8000-000000000003', 'd3000000-0000-4000-8000-000000000003', 'comment', 5),
  ('d1000000-0000-4000-8000-000000000004', 'd3000000-0000-4000-8000-000000000004', 'post', 10),
  ('d1000000-0000-4000-8000-000000000008', 'd3000000-0000-4000-8000-000000000006', 'post', 10)
) as v(user_id, community_id, contribution_type, points)
where not exists (
  select 1 from public.community_contributions c
  where c.user_id = v.user_id and c.community_id = v.community_id and c.contribution_type = v.contribution_type
);
